import re

from moler.exceptions import CommandFailure, ParsingDone
from moler.util.converterhelper import ConverterHelper

from ta_moler.cmd.shared.aashell.genericaashell import GenericAashell

__author__ = "Piotr Smerdzynski"
__copyright__ = "Copyright (C) 2019, Nokia"
__email__ = "piotr.smerdzynski@nokia.com"


class GetCellMapping(GenericAashell):
    """getCellMapping command class."""

    def __init__(self, connection, options="@RROMexe", prompt=None, newline_chars=None, runner=None):
        """
        Command getCellMapping.

        :param connection: moler connection to device, terminal when command is executed
        :param options: parameter with which the command will be executed
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GetCellMapping, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.current_ret = []
        self._column_names = None
        self._converter = ConverterHelper.get_converter_helper()
        self._line_number = -1

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "getCellMapping"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_command_failure(line)
                self._parse_cells_data(line)
            except ParsingDone:
                pass
        return super(GetCellMapping, self).on_new_line(line, is_full_line)

    _re_failure = re.compile(r"(?P<ERROR>Process .* not registered to AaShell)")

    def _parse_command_failure(self, line):
        """
        Raise exception CommandFailure if process is not registered to AaShell.

        :param line: line to be parsed
        :return: None but raises CommandFailure.
        """
        if self._regex_helper.search_compiled(GetCellMapping._re_failure, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR')}"))
            raise ParsingDone

    def _parse_cells_data(self, line):
        """
        Add cells mapping to result list of dicts.

        :param line: line to be parsed
        """
        if not self._column_names:
            self._column_names = line.split()
        else:
            self._line_number += 1
            values = line.split()
            self.current_ret.append({})
            for key, value in zip(self._column_names, values):
                if value.startswith("0x"):
                    self.current_ret[self._line_number][f"{key}_raw"] = value
                    self.current_ret[self._line_number][key] = int(value, 16)
                elif key == "chBw":
                    self.current_ret[self._line_number][f"{key}_raw"] = value
                    self.current_ret[self._line_number][key] = self._converter.to_bytes(value, binary_multipliers=False)[0]
                else:
                    value = int(value) if value.isdigit() else value
                    self.current_ret[self._line_number][key] = value
        raise ParsingDone


